// Decorative SVG shapes; all outcome and direction data comes from recorded combat.
const flame='<path d="M0-43C18-18 1-15 15-2C27 15 12 31 0 30C-23 30-27 8-15-9C-17 8-5 3-3-7C1-18-7-25 0-43Z" fill="#ee7946"/><path d="M0-12C12 5 9 19 0 24C-12 17-8 6 0-12Z" fill="#ffcd78"/>';
const rays=Array.from({length:12},(_,i)=>`<path transform="rotate(${i*30})" d="M-3-37 0-54 3-37"/>`).join('');
const seal='<path d="M-46-48 46-48 52-42 52 42 46 48-46 48-52 42-52-42Z" fill="#55473b" stroke="#e5c286" stroke-width="2"/><path d="M-40-35H40V35H-40Z" fill="#172a28" stroke="#bea576"/><path d="M-29 18-12-13 0 1 12-22 31 18Z" fill="#aa9570" stroke="#e6c991" stroke-width="1.5"/><path d="M-31 24H31M-33-25H-21M21-25H33" stroke="#e6c991" stroke-width="2"/>';
const fragments=(cls,count)=>Array.from({length:count},(_,i)=>`<i class="${cls}" style="--angle:${i*360/count}deg;--delay:${i*40}ms"></i>`).join('');
const impact=(id,dx,dy,html)=>`<div class="charge-impact ${id}-impact" style="left:${dx}px;top:${dy}px">${html}</div>`;
export const CHARGED_ART={
 inferno:{name:'离火焚天',subtitle:'流 焰 · 蓄 势',art:`<svg viewBox="-150 -155 300 300"><ellipse class="inferno-seal" cy="88" rx="87" ry="20"/><ellipse class="inferno-seal inner" cy="88" rx="68" ry="13"/>${[-70,-38,0,38,70].map((x,i)=>`<g transform="translate(${x} ${65-Math.abs(x)*.6}) scale(.7)"><g class="inferno-flame" style="--delay:${i*150}ms">${flame}</g></g>`).join('')}<path class="inferno-rune" d="M-95 40Q0 105 95 40M-70 17Q0 75 70 17"/>${[-58,-24,25,58].map((x,i)=>`<circle class="inferno-ember" cx="${x}" cy="${5+i*8}" r="2" style="--delay:${i*330}ms"/>`).join('')}</svg>`,
  cast:({dx,dy})=>[-1,0,1].map((lane,i)=>`<div class="inferno-stream" style="--lane:${lane*18}px;--delay:${i*55}ms"><svg viewBox="0 -40 160 80"><path d="M0 0Q38-32 75-7T153 0Q110 33 67 9T0 0" fill="#ee7946"/><path d="M35 0Q81-9 148 0Q77 12 35 0" fill="#ffda88"/></svg></div>`).join('')+impact('inferno',dx,dy,`<svg class="inferno-pillar" viewBox="-60 -100 120 150"><g transform="translate(0 -7) scale(1.7)">${flame}</g></svg><span class="inferno-ground-burst"></span>${fragments('inferno-spark',9)}`)},
 solar:{name:'赤日临空',subtitle:'聚 日 · 蓄 势',art:`<svg viewBox="-150 -155 300 300"><g transform="translate(0 -122)"><circle class="solar-halo" r="53"/><g class="solar-corona">${rays}</g><circle class="solar-core" r="30"/><circle class="solar-core-inner" r="21"/><path class="solar-meridian" d="M-42 42Q0 75 42 42M-57 53Q0 100 57 53"/></g><path class="solar-thread" d="M-26 55Q-45 8-19-40M26 55Q45 8 19-40"/></svg>`,
  cast:({dx,dy})=>`<div class="solar-flight"><span></span></div>`+impact('solar',dx,dy,`<span class="solar-fall"></span><span class="solar-burst"></span><span class="solar-shockwave"></span>${fragments('solar-spark',8)}`)},
 mountain:{name:'镇岳印',subtitle:'凝 岳 · 蓄 势',art:`<svg viewBox="-150 -155 300 300"><ellipse class="mountain-array" cy="88" rx="92" ry="21"/><path class="mountain-array" d="M-82 87H82M-62 73 62 101M-62 101 62 73"/><g class="mountain-seal" transform="translate(0 -49) scale(.8)">${seal}</g>${[-75,-49,48,77].map((x,i)=>`<g transform="translate(${x} ${40+i%2*18})"><path class="mountain-rock" style="--delay:${i*180}ms" d="M-9-4-3-12 9-7 12 5 0 10-10 4Z"/></g>`).join('')}</svg>`,
  cast:({dx,dy})=>impact('mountain',dx,dy,`<svg class="mountain-drop" viewBox="-70 -65 140 130">${seal}</svg><span class="mountain-shockwave"></span>${fragments('mountain-debris',8)}`)}
};
